using Frame.Core;

// --audio-continuity <packet-times.txt>...: applies the clip audio rules (Frame.Core.MediaContinuity) to real clips.
if (args.Length > 1 && args[0] == "--audio-continuity")
{
    foreach (var file in args.Skip(1))
    {
        var times = File.ReadAllLines(file).Select(l => double.Parse(l.Trim().TrimEnd(','), System.Globalization.CultureInfo.InvariantCulture)).ToArray();
        var report = MediaContinuity.Audio(times); string? problem = MediaContinuity.AudioProblem(report);
        Console.WriteLine($"{Path.GetFileName(file)}: packets {report.Packets}, holes {report.Holes}, overlaps {report.Overlaps}, duplicates {report.Duplicates}, longest {report.LongestStepMs} ms, shortest {report.ShortestStepMs} ms, first irregular {string.Join(", ", report.Irregular.Take(3).Select(x => $"{x.At:0.000}s:{x.StepMs}ms"))} -> {(problem == null ? "ACCEPTED" : "REJECTED: " + problem)}");
    }
    return 0;
}
int passed = 0, failed = 0;
void Test(string name, Action action) { try { action(); Console.WriteLine("PASS " + name); passed++; } catch (Exception e) { Console.WriteLine("FAIL " + name + ": " + e); failed++; } }
void Assert(bool value) { if (!value) throw new Exception("Assertion failed"); }
void Throws(Action action) { try { action(); } catch { return; } throw new Exception("Expected failure"); }
void RedactionCheck()
{
    string profile = "C:\\Users\\Jane.Doe";
    string text = "Saved C:\\Users\\Jane.Doe\\Videos\\FRAME\\a.mp4 and {\"p\":\"C:\\\\Users\\\\Jane.Doe\\\\x\"} c:/users/jane.doe/y jane.doe on JANE-PC mail jane@example.org token=abc123 \"password\": \"pw1\" GPU NVIDIA GeForce RTX 4090 D:\\Captures\\b.mp4";
    string r = DiagnosticsRedaction.Redact(text, profile, "Jane.Doe", "JANE-PC");
    Assert(!r.Contains("Jane", StringComparison.OrdinalIgnoreCase) && !r.Contains("JANE-PC") && !r.Contains("jane@example.org") && !r.Contains("abc123") && !r.Contains("pw1"));
    Assert(r.Contains("%USERPROFILE%\\Videos\\FRAME\\a.mp4") && r.Contains("{\"p\":\"%USERPROFILE%\\\\x\"}") && r.Contains("%USERPROFILE%/y") && r.Contains("<user> on <computer>") && r.Contains("<email>") && r.Contains("token=<redacted>") && r.Contains("NVIDIA GeForce RTX 4090") && r.Contains("D:\\Captures\\b.mp4"));
    Assert(DiagnosticsRedaction.Redact("Bob uses Bobby", null, "Bo", null) == "Bob uses Bobby");
}
