    Test("Capture settings: only capture-affecting changes need a Shadow restart", () => { var a = new Settings(); Settings With(Action<Settings> change) { var b = System.Text.Json.JsonSerializer.Deserialize<Settings>(System.Text.Json.JsonSerializer.Serialize(a))!; change(b); return b; } Assert(!CaptureSettings.Differ(a, With(_ => { }))); foreach (var change in new Action<Settings>[] { b => b.VisualMode = "light", b => b.ShowSaveNotifications = false, b => b.StartWithWindows = true, b => b.StartShadowOnLaunch = true, b => b.PinkEffects = ["dogs"], b => b.ReplaySeconds = 900, b => b.Hotkeys = [] }) Assert(!CaptureSettings.Differ(a, With(change))); foreach (var change in new Action<Settings>[] { b => b.Fps = 30, b => b.OutputHeight = 720, b => b.BitrateMbps = 6, b => b.ReplayBudgetMb = 2048, b => b.OutputDevice = "x", b => b.InputDevice = "y", b => b.Cursor = false, b => b.Combined = true, b => b.FfmpegPath = "C:\\f\\ffmpeg.exe", b => b.Encoder = "libx264" }) Assert(CaptureSettings.Differ(a, With(change))); });
    // Capture-page display map (DisplayLayout): proportions, no overlap, inside the canvas, order preserved, minimum card size.
    DisplayArrangement Map(double width, params Box[] m) { var a = DisplayLayout.Arrange(m, width, 88, 132); Assert(a.Cards.Length == m.Length && a.Height >= 88 && a.Height <= 132 && a.Width == width); for (int i = 0; i < m.Length; i++) { var c = a.Cards[i]; Assert(c.X >= 0 && c.Y >= 0 && c.Right <= a.Width + 1e-9 && c.Bottom <= a.Height + 1e-9 && c.Width >= 47 && c.Height >= 33); for (int j = i + 1; j < m.Length; j++) { var o = a.Cards[j]; Assert(!c.Overlaps(o)); Assert(Math.Max(Math.Max(o.X - c.Right, c.X - o.Right), Math.Max(o.Y - c.Bottom, c.Y - o.Bottom)) >= 3.99); } } return a; }
    bool Near(double a, double b, double tolerance) => Math.Abs(a - b) <= tolerance * Math.Max(Math.Abs(a), Math.Abs(b));
    Test("Display map: one 1080p monitor keeps 16:9, is centred and capped at the canvas height", () => { foreach (double w in new[] { 278d, 453, 1100 }) { var c = Map(w, new Box(0, 0, 1920, 1080)).Cards[0]; Assert(Near((c.Width + 4) / (c.Height + 4), 16 / 9d, .02) && c.Height + 4 <= 132 && Math.Abs(c.X + c.Width / 2 - w / 2) <= 1); } });
    Test("Display map: 1440p + 1080p side by side keep relative size and left-to-right order", () => { var a = Map(278, new Box(0, 0, 2560, 1440), new Box(2560, 0, 1920, 1080)); Assert(a.Cards[0].Right < a.Cards[1].X && Near(a.Cards[0].Width + 4, (a.Cards[1].Width + 4) * 2560 / 1920, .04) && Near(a.Cards[0].Height + 4, (a.Cards[1].Height + 4) * 1440 / 1080, .04) && a.Cards[0].Y == a.Cards[1].Y); });
    Test("Display map: 1080p at negative X, 1440p primary, 4K TV right; 4K TV beside two 1080p", () => { foreach (double w in new[] { 278d, 453 }) { var a = Map(w, new Box(-1920, 0, 1920, 1080), new Box(0, 0, 2560, 1440), new Box(2560, 0, 3840, 2160)); Assert(a.Cards[0].Right < a.Cards[1].X && a.Cards[1].Right < a.Cards[2].X && a.Cards[2].Width > a.Cards[1].Width && a.Cards[1].Width > a.Cards[0].Width && Near(a.Cards[2].Height + 4, (a.Cards[1].Height + 4) * 1.5, .06)); var b = Map(w, new Box(0, 0, 1920, 1080), new Box(1920, 0, 1920, 1080), new Box(3840, 0, 3840, 2160)); Assert(Math.Abs(b.Cards[0].Width - b.Cards[1].Width) <= 1 /* whole-DIP edges */ && b.Cards[1].Right < b.Cards[2].X && Near(b.Cards[2].Width + 4, 2 * (b.Cards[0].Width + 4), .06)); } });
    Test("Display map: monitor above / below the primary and vertical stacks keep top-to-bottom order", () => { var above = Map(278, new Box(0, -2160, 3840, 2160), new Box(960, 0, 1920, 1080)); Assert(above.Cards[0].Bottom < above.Cards[1].Y && above.Cards[0].Width > above.Cards[1].Width); var below = Map(278, new Box(0, 0, 1920, 1080), new Box(-960, 1080, 3840, 2160)); Assert(below.Cards[0].Bottom < below.Cards[1].Y && below.Cards[1].X < below.Cards[0].X); var stack = Map(278, new Box(0, -1080, 1920, 1080), new Box(0, 0, 1920, 1080), new Box(0, 1080, 1920, 1080)); Assert(stack.Cards[0].Bottom < stack.Cards[1].Y && stack.Cards[1].Bottom < stack.Cards[2].Y && stack.Height == 132); });
    Test("Display map: ultrawide 3440x1440 + portrait 1080x1920, and a tiny monitor beside an 8K one stays clickable", () => { var a = Map(278, new Box(0, 0, 3440, 1440), new Box(3440, -240, 1080, 1920)); Assert(a.Cards[0].Width > 2 * a.Cards[0].Height && a.Cards[1].Height > a.Cards[1].Width && a.Cards[0].Right < a.Cards[1].X && a.Cards[1].Y < a.Cards[0].Y); var t = Map(278, new Box(0, 0, 7680, 4320), new Box(7680, 0, 800, 600)); Assert(t.Cards[1].Width >= 47 && t.Cards[1].Height >= 33 && t.Cards[0].Width > 3 * t.Cards[1].Width); });
    Test("Display map: random desktop arrangements never overlap, stay inside and keep a minimum card size", () => { var r = new Random(11); var sizes = new[] { (1920, 1080), (2560, 1440), (3840, 2160), (3440, 1440), (1080, 1920), (1280, 1024), (7680, 4320) }; for (int run = 0; run < 400; run++) { var list = new List<Box>(); int n = 1 + r.Next(4); for (int i = 0; i < n; i++) { var (w, h) = sizes[r.Next(sizes.Length)]; if (list.Count == 0) { list.Add(new(r.Next(-4000, 4000), r.Next(-3000, 3000), w, h)); continue; } var u = Box.Union(list); list.Add(r.Next(4) switch { 0 => new(u.Right, u.Y + r.Next(-h + 1, u.Height), w, h), 1 => new(u.X - w, u.Y + r.Next(-h + 1, u.Height), w, h), 2 => new(u.X + r.Next(-w + 1, u.Width), u.Bottom, w, h), _ => new(u.X + r.Next(-w + 1, u.Width), u.Y - h, w, h) }); } var a = DisplayLayout.Arrange(list, 278, 88, 180); for (int i = 0; i < n; i++) { var c = a.Cards[i]; Assert(c.X >= 0 && c.Y >= 0 && c.Right <= 278 && c.Bottom <= a.Height && a.Height <= 180 && c.Width >= 47 && c.Height >= 33); for (int j = i + 1; j < n; j++) Assert(!c.Overlaps(a.Cards[j])); } } });
    Test("Display map (readable): every card fits number + full resolution, the TV stays above, no overlap, at 278 and 453 DIP", () => { var setups = new[] { new[] { new Box(0, -2160, 3840, 2160), new Box(-1920, 0, 1920, 1080), new Box(0, 0, 1920, 1080), new Box(1920, 0, 2560, 1440) }, new[] { new Box(-1920, 180, 1920, 1080), new Box(0, 0, 2560, 1440), new Box(2560, -200, 3840, 2160) }, new[] { new Box(0, 0, 3440, 1440), new Box(3440, -240, 1080, 1920) }, new[] { new Box(0, 0, 1920, 1080) } }; foreach (var m in setups) foreach (double w in new[] { 278d, 453 }) { var a = DisplayLayout.ArrangeReadable(m, w); Assert(a.Height <= 176 && a.Cards.All(c => c.X >= 0 && c.Y >= 0 && c.Right <= w && c.Bottom <= a.Height && c.Width >= DisplayLayout.CardWidth - 1 && c.Height >= DisplayLayout.CardHeight - 1)); for (int i = 0; i < m.Length; i++) for (int j = i + 1; j < m.Length; j++) Assert(!a.Cards[i].Overlaps(a.Cards[j])); } var tv = DisplayLayout.ArrangeReadable(setups[0], 278); Assert(tv.Cards[0].Bottom <= tv.Cards.Skip(1).Min(c => c.Y) && tv.Cards[1].Right < tv.Cards[2].X && tv.Cards[2].Right < tv.Cards[3].X); Assert(DisplayLayout.ArrangeReadable(setups[3], 453).Height <= 132); var five = Enumerable.Range(0, 5).Select(i => new Box(i * 1920, 0, 1920, 1080)).ToArray(); var narrow = DisplayLayout.ArrangeReadable(five, 278); Assert(narrow.Cards.All(c => c.Width >= DisplayLayout.NarrowCardWidth - 1 && c.Height >= DisplayLayout.NarrowCardHeight - 1 && c.Right <= 278)); });
    Test("Shadow on/off hotkey: new settings have it unset; older files gain it unset, every binding (Alt+Z, Ctrl+Alt+F) kept", () => { Assert(new Settings().Hotkeys.Single(h => h.Action == "Shadow") == new Hotkey("Shadow", 0, 0)); var path = Path.Combine(folder, "pre-shadow.json"); var s = new Settings { OutputDirectory = folder, Hotkeys = [new("Record", 6, 0x52), new("Pause", 6, 0x50), new("Replay", 1, 0x5A), new("Monitors", 6, 0x4D), new("Open", 3, 0x46)] }; SettingsStore.Save(path, s); var loaded = SettingsStore.Load(path); Assert(loaded.Hotkeys.Take(5).SequenceEqual(s.Hotkeys) && loaded.Hotkeys[5] == new Hotkey("Shadow", 0, 0)); var set = SettingsStore.Load(path); set.Hotkeys = set.Hotkeys.Select(h => h.Action == "Shadow" ? new Hotkey("Shadow", 3, 0x78) : h).ToArray(); SettingsStore.Save(path, set); Assert(SettingsStore.Load(path).Hotkeys.Single(h => h.Action == "Shadow") == new Hotkey("Shadow", 3, 0x78) && SettingsStore.Load(path).Hotkeys.Count(h => h.Action == "Shadow") == 1); });
    Test("Shadow on/off hotkey cannot take Alt+Z, Ctrl+Alt+F or a manual recording key; a free combination is accepted", () => { Hotkey[] others = [new("Replay", 1, 0x5A), new("Open", 3, 0x46), new("Record", 6, 0x52), new("Pause", 6, 0x50)]; Throws(() => HotkeyChoice.Create("Shadow", 1, 0x5A, others)); Throws(() => HotkeyChoice.Create("Shadow", 3, 0x46, others)); Throws(() => HotkeyChoice.Create("Shadow", 6, 0x52, others)); Assert(HotkeyChoice.Create("Shadow", 3, 0x78, others) == new Hotkey("Shadow", 3, 0x78)); Throws(() => new Settings { OutputDirectory = folder, Hotkeys = [new("Replay", 1, 0x5A), new("Shadow", 1, 0x5A)] }.Validate()); });
    Test("Primary display placement: centred in the work area, size converted between scales and clamped, negative coordinates", () => { var work = new Box(0, 0, 2560, 1400); var c = WindowPlacement.CentreOn(new Box(-1920, 200, 1280, 800), work, 1, 1); Assert(c == new Box(640, 300, 1280, 800)); var scaled = WindowPlacement.CentreOn(new Box(3840, 0, 2560, 1600), new Box(0, 0, 1920, 1040), 2, 1); Assert(scaled.Width == 1280 && scaled.Height == 800 && scaled.X == 320 && scaled.Y == 120); var big = WindowPlacement.CentreOn(new Box(0, -2160, 3840, 2160), new Box(0, 0, 1920, 1040), 1, 1); Assert(big == new Box(0, 0, 1920, 1040)); var offset = WindowPlacement.CentreOn(new Box(0, 0, 1000, 700), new Box(-2560, -400, 2560, 1400), 1.5, 1.25); Assert(offset.X >= -2560 && offset.Right <= 0 && offset.Y >= -400 && offset.Bottom <= 1000 && Math.Abs(offset.Width - 833) <= 1); });
    Test("Log retention: 14 days, 50 MB in total, newest file always kept; daily names with rollover index", () => { var now = new DateTime(2026, 10, 15, 12, 0, 0, DateTimeKind.Utc); var files = new[] { new LogFile("new", 4_000_000, now), new LogFile("old", 1000, now.AddDays(-15)), new LogFile("mid", 5_000_000, now.AddDays(-3)) }; var del = LogRetention.Expired(files, now); Assert(del.SequenceEqual(["old"])); var many = Enumerable.Range(0, 20).Select(i => new LogFile("f" + i, 5_000_000, now.AddHours(-i))).ToArray(); var cut = LogRetention.Expired(many, now); Assert(cut.Count == 10 && !cut.Contains("f0") && cut.Contains("f19")); Assert(LogRetention.Expired([new LogFile("only", 90_000_000, now.AddDays(-30))], now).Count == 0); Assert(LogRetention.FileName(new DateTime(2026, 10, 15), 0) == "FRAME-20261015.log" && LogRetention.FileName(new DateTime(2026, 10, 15), 2) == "FRAME-20261015-2.log"); });
