    // 0.5.5 display selection recovery (Frame.Core DisplaySelection): by device id, Windows' primary flag, never "index 0".
    CaptureTarget D(string id, int x, int y, int w = 1920, int h = 1080) => new(id, id, new Box(x, y, w, h));
    Test("Primary policy: fresh settings follow primary after device renumbering, primary changes and a reload", () =>
    {
        var path = Path.Combine(folder, "primary-policy.json"); var s = new Settings { OutputDirectory = folder };
        var first = new[] { D("SIDE", -1920, 0), D("MAIN", 0, 0) };
        Assert(DisplaySelection.FollowsPrimary(first, s, "MAIN") && DisplaySelection.Resolve(first, s, "MAIN").Selected.SequenceEqual(["MAIN"]));
        s.FollowPrimaryDisplay = true; SettingsStore.Save(path, s);
        var after = new[] { D("MAIN", -1920, 0), D("NEW-ID", 0, 0) };
        var loaded = SettingsStore.Load(path);
        Assert(DisplaySelection.Resolve(after, loaded, "NEW-ID").Selected.SequenceEqual(["NEW-ID"]) && loaded.SelectedDisplays.Length == 0);
        Assert(DisplaySelection.Resolve([], loaded, null).Recovery == DisplayRecovery.NoDisplays);
        Assert(DisplaySelection.Resolve(after.Reverse().ToArray(), loaded, "NEW-ID").Selected.SequenceEqual(["NEW-ID"]));
    });
    Test("Legacy display migration: primary becomes a policy; secondary and multiple choices remain explicit", () =>
    {
        var displays = new[] { D("SIDE", -1920, 0), D("MAIN", 0, 0) };
        foreach (var ids in new[] { Array.Empty<string>(), new[] { "MAIN" }, new[] { "SIDE" }, new[] { "MAIN", "SIDE" }, new[] { "GONE" } })
        {
            var s = new Settings { SelectedDisplays = ids };
            Assert(DisplaySelection.FollowsPrimary(displays, s, "MAIN") == (ids.Length == 0 || ids.SequenceEqual(["MAIN"])));
        }
        Assert(!DisplaySelection.FollowsPrimary(displays, new Settings { FollowPrimaryDisplay = false, SelectedDisplays = ["MAIN"] }, "MAIN"));
        Assert(DisplaySelection.Resolve(displays, new Settings { FollowPrimaryDisplay = true, SelectedDisplays = ["SIDE"] }, "MAIN").Selected.SequenceEqual(["MAIN"]));
    });
    Test("Temporary display recovery survives reload without replacing secondary or multi-display preferences", () =>
    {
        var path = Path.Combine(folder, "display-recovery.json");
        foreach (var ids in new[] { new[] { "SIDE" }, new[] { "SIDE", "TV" } })
        {
            var s = new Settings { OutputDirectory = folder, FollowPrimaryDisplay = false, SelectedDisplays = ids };
            SettingsStore.Save(path, s);
            Assert(DisplaySelection.Resolve([D("MAIN", 0, 0)], s, "MAIN").Selected.SequenceEqual(["MAIN"]));
            SettingsStore.Save(path, s); var loaded = SettingsStore.Load(path);
            Assert(loaded.SelectedDisplays.SequenceEqual(ids) && loaded.FollowPrimaryDisplay == false);
            var connected = new[] { D("MAIN", 0, 0), D("SIDE", -1920, 0), D("TV", 1920, 0) };
            Assert(DisplaySelection.Resolve(connected, loaded, "MAIN").Selected.SequenceEqual(ids));
            if (ids.Length == 2) Assert(DisplaySelection.Resolve(connected[..2], loaded, "MAIN").Selected.SequenceEqual(["SIDE"]));
        }
    });
    Test("Primary policy roundtrip preserves all other settings and capture profile", () =>
    {
        var path = Path.Combine(folder, "primary-other-settings.json");
        var s = new Settings { OutputDirectory = folder, Fps = 120, OutputHeight = 1440, BitrateMbps = 35, ReplaySeconds = 900,
            DesktopAudio = false, Microphone = true, Cursor = false, Combined = true, StartWithWindows = true, StartShadowOnLaunch = true,
            VisualMode = "dark", MinimizeOnGameStart = false, ShowSaveNotifications = false, FollowPrimaryDisplay = true };
        SettingsStore.Save(path, s); var loaded = SettingsStore.Load(path);
        DisplaySelection.Resolve([D("SIDE", -1920, 0), D("MAIN", 0, 0)], loaded, "MAIN");
        Assert(System.Text.Json.JsonSerializer.Serialize(s) == System.Text.Json.JsonSerializer.Serialize(loaded));
        loaded.FollowPrimaryDisplay = false; loaded.SelectedDisplays = ["SIDE"];
        Assert(!CaptureSettings.Differ(s, loaded));
    });
    Test("Display selection: one display, nothing saved (first launch) selects it; a valid saved one is kept unchanged", () => { var one = new[] { D("A", 0, 0) }; var first = DisplaySelection.Resolve(one, [], "A"); Assert(first.Recovery == DisplayRecovery.Initial && first.Selected.SequenceEqual(["A"]) && first.Changed); var kept = DisplaySelection.Resolve(one, ["A"], "A"); Assert(kept.Recovery == DisplayRecovery.None && kept.Selected.SequenceEqual(["A"]) && !kept.Changed && kept.Missing.Length == 0); });
    Test("Display selection: the saved display is gone → Windows' primary even when it is not listed first (negative coordinates)", () => { var two = new[] { D("TV", -3840, -2160, 3840, 2160), D("MAIN", 0, 0, 2560, 1440) }; var c = DisplaySelection.Resolve(two, ["OLD-TV"], "MAIN"); Assert(c.Recovery == DisplayRecovery.Primary && c.Selected.SequenceEqual(["MAIN"]) && c.Missing.SequenceEqual(["OLD-TV"])); });
    Test("Display selection: three displays, one of two saved displays gone → the remaining one (not the primary); all gone → primary", () => { var three = new[] { D("L", -1920, 180), D("P", 0, 0, 2560, 1440), D("TV", 2560, -200, 3840, 2160) }; var partial = DisplaySelection.Resolve(three, ["TV", "GONE"], "P"); Assert(partial.Recovery == DisplayRecovery.Partial && partial.Selected.SequenceEqual(["TV"]) && partial.Missing.SequenceEqual(["GONE"])); var none = DisplaySelection.Resolve(three, ["X", "Y"], "P"); Assert(none.Recovery == DisplayRecovery.Primary && none.Selected.SequenceEqual(["P"]) && none.Missing.Length == 2); var multi = DisplaySelection.Resolve(three, ["L", "TV"], "P"); Assert(multi.Recovery == DisplayRecovery.None && multi.Selected.SequenceEqual(["L", "TV"])); });
    Test("Display selection: primary changes keep a connected deliberate choice; a disconnected one falls back to the new primary", () => { var after = new[] { D("OLD-PRIMARY", -2560, 0, 2560, 1440), D("NEW-PRIMARY", 0, 0) }; Assert(DisplaySelection.Resolve(after, ["OLD-PRIMARY"], "NEW-PRIMARY").Recovery == DisplayRecovery.None); var moved = DisplaySelection.Resolve([D("NEW-PRIMARY", 0, 0), D("SIDE", 1920, 0)], ["OLD-PRIMARY"], "NEW-PRIMARY"); Assert(moved.Selected.SequenceEqual(["NEW-PRIMARY"])); });
    Test("Display selection: no primary id → the display at the desktop origin (Windows' primary is always at 0,0), then the first; empty list keeps the saved selection", () => { var noFlag = new[] { D("LEFT", -1920, 0), D("TV", 0, -2160, 3840, 2160), D("ORIGIN", 0, 0) }; Assert(DisplaySelection.Resolve(noFlag, ["GONE"], null).Selected.SequenceEqual(["ORIGIN"])); Assert(DisplaySelection.Primary(noFlag, "unknown")!.Id == "ORIGIN"); Assert(DisplaySelection.Primary([D("A", 10, 10), D("B", 3000, 0)], null)!.Id == "A"); var empty = DisplaySelection.Resolve([], ["A", "B"], null); Assert(empty.Recovery == DisplayRecovery.NoDisplays && empty.Selected.SequenceEqual(["A", "B"]) && !empty.Changed); Assert(DisplaySelection.Primary([], null) == null); });
    Test("Display selection: blank and duplicate saved ids are ignored; ids are matched exactly, not by position", () => { var c = DisplaySelection.Resolve([D("A", 0, 0), D("B", 1920, 0)], ["", " ", "B", "B"], "A"); Assert(c.Recovery == DisplayRecovery.None && c.Selected.SequenceEqual(["B"])); var renumbered = DisplaySelection.Resolve([D(@"\\.\DISPLAY2", 0, 0)], [@"\\.\DISPLAY1"], @"\\.\DISPLAY2"); Assert(renumbered.Recovery == DisplayRecovery.Primary && renumbered.Selected.SequenceEqual([@"\\.\DISPLAY2"])); });
    // 0.5.5 hotkey labels (Frame.Core KeyLabels): layout characters for OEM keys, established names for the rest.
