    Test("Hotkey labels: fixed names for digits, letters, numpad, F-keys, Scroll Lock, Pause; OEM keys are left to the layout", () => { Assert(KeyLabels.Named(0x31) == "1" && KeyLabels.Named(0x5A) == "Z" && KeyLabels.Named(0x60) == "Num 0" && KeyLabels.Named(0x69) == "Num 9" && KeyLabels.Named(0x70) == "F1" && KeyLabels.Named(0x87) == "F24" && KeyLabels.Named(0x91) == "Scroll Lock" && KeyLabels.Named(0x13) == "Pause" && KeyLabels.Named(0x22) == "Page Down"); foreach (uint oem in new uint[] { 0xBA, 0xBB, 0xBC, 0xBD, 0xBE, 0xBF, 0xC0, 0xDB, 0xDC, 0xDD, 0xDE, 0xDF, 0xE2 }) Assert(KeyLabels.Named(oem) == null); Assert(KeyLabels.LayoutCulture(0x04140414, System.Globalization.CultureInfo.InvariantCulture).Name == "nb-NO" && KeyLabels.LayoutCulture(0, System.Globalization.CultureInfo.InvariantCulture) == System.Globalization.CultureInfo.InvariantCulture); });
